  chart(context.loaded.weather, {
    axes: true,
    color: palette({
      sun: "#e7ba52",
      fog: "#dfdfdf",
      drizzle: "#79a1d5",
      rain: "#1f77b4",
      snow: "#9467bd",
    }),
  })
    .flow(
      derive((d) =>
        d.map((row) => ({
          month: MONTHS[new Date(row.date).getMonth()],
          ...row,
        })),
      ),
      spread({ by: "month", dir: "x" }),
      stack({
        by: field("weather").sort(["sun", "fog", "drizzle", "rain", "snow"]),
        dir: "y",
