import { layer, map, rect, ribbon, spreadX, stackY, v } from "gofish-graphics";
import { density1d } from "fast-kde";
import { groupBy } from "lodash";
import { penguins } from "./dataset";
const container = document.getElementById("app");
spreadX(
  { spacing: 64, sharedScale: true },
  map(groupBy(penguins, "Species"), (d, species) => {
    const density = Array.from(
      density1d(d.map((p) => p["Body Mass (g)"]).filter((w) => w !== null)),
    );
    return layer({}, [
      stackY(
        { alignment: "middle" },
        map(density, (d) =>
          rect({
            y: -d.x / 40,
            w: d.y * 100000,
            h: 0,
            fill: v(species),
          }).name(`${species}-${d.x}`),
        ),
      ),
    ]).relate((names) => [
      ribbon(
        { dir: "y", opacity: 1, mixBlendMode: "normal" },
        map(density, (d) => names[`${species}-${d.x}`]),
      ),
    ]);
  }),
).render(container, {
  axes: true,
});

import { chart, derive, rect, repeat, spread } from "gofish-graphics";
import _ from "lodash";
import { seafood } from "./dataset";
const container = document.getElementById("app");
// x-axis at the bottom (y-end) so the lake labels sit under the upward-
// filling waffle columns rather than above them.
chart(seafood, { axes: { x: { side: "end" } } })
  .flow(
    // Bottom-align the lake columns (y-down free space: "end" = bottom) so the
    // waffles sit on a shared baseline and fill upward rather than hang down.
    spread({ by: "lake", spacing: 8, dir: "x", axes: false, alignment: "end" }),
    derive((d) => d.flatMap((d) => repeat(d, "count"))),
    derive((d) => _.chunk(d, 5)),
    // Reverse the rows so the ragged (partial) last row lands at the TOP and
    // the full rows fill the baseline upward (y-down free space).
    spread({ spacing: 2, dir: "y", reverse: true }),
    spread({ spacing: 2, dir: "x" }),
  )
  .mark(rect({ w: 8, h: 8, fill: "species" }))
  .render(container, {});

import { Constraint, chart, image, layer, spread, text } from "gofish-graphics";
import bottlePng from "./wilsonblanco.png";
const bottleData = [
  { category: "Marketing", amount: 6 },
  { category: "Pretentiousness", amount: 7 },
  { category: "Sulfites", amount: 2 },
  { category: "Tannins", amount: 3 },
  { category: "Water", amount: 40 },
  { category: "Grape juice", amount: 42 },
];
const container = document.getElementById("app");
// The cut ties each slice's image band to data order (slice i = band i,
// top→bottom). To land Grape juice (the bulk) at the BOTTOM showing the
// bottle BODY, it must be the LAST data row (bottom band) AND positioned
// last — so reverse the data and keep `reverse: true` on the spread.
chart([...bottleData].reverse())
  .flow(spread({ dir: "y", spacing: 20, reverse: true }))
  .mark(
    image({ href: bottlePng, w: 193, h: 600 }).cut({
      dir: "y",
      size: "amount",
      inset: 4,
    }),
  )
  .layer(
    chart().mark((data) =>
      layer(
        data.map((d) =>
          layer([
            d.name("slice"),
            text({
              fontSize: 18,
              fontWeight: "bold",
              fill: "#1c5e20",
              text: d.datum.category,
            }).name("label"),
            text({
              fontSize: 36,
              fontFamily: "Impact",
              fill: "#1c5e20",
              text: `${d.datum.amount}`,
            }).name("amount"),
          ]).relate(({ slice, label, amount }) => [
            Constraint.align({ y: "middle" }, [slice, label]),
            Constraint.distribute({ dir: "x", spacing: 12 }, [slice, label]),
            Constraint.align({ x: "middle" }, [slice, amount]),
            Constraint.align({ y: "middle" }, [slice, amount]),
          ]),
        ),
      ),
    ),
  )
  .render(container, { axes: false });
